SET search_path TO dbo, public;

-- ==== view GetAssociatedRecipientForSMS ====
CREATE OR REPLACE VIEW dbo.getassociatedrecipientforsms AS
SELECT DISTINCT ar.smstemplatecode, ltrim(rtrim((cc.contactcardcode)::text)) AS contactcardcode, cc.mobile FROM dbo.sms_associatedrecipient AS ar, dbo.contactgroup AS cg, dbo.contactgroupdetail AS cgd, dbo.contactcard AS cc WHERE ((((ar.contactgroupcode = cg.contactgroupcode) AND (cg.contactgroupcode = cgd.contactgroupcode)) AND (cgd.contactcardcode = cc.contactcardcode)) AND (cc.useforsms = 'Y'));

