-- ==== view View_CRS_ItemStockPosition ====
CREATE OR REPLACE VIEW dbo.view_crs_itemstockposition AS
SELECT cl.name AS branchname, i.icode AS icode, i.customicode AS aliasname, i.name AS itemname, sum(gd.currqty) AS branchstock, max(gd.lastfetchedon) AS lastfetchedon, (((sum(dbo.tsql_datediff('minute', gd.lastfetchedon, localtimestamp(3))) / 60))::integer + round((((sum(dbo.tsql_datediff('minute', gd.lastfetchedon, localtimestamp(3))) % 60) / 60.00))::numeric, 2)) AS age FROM dbo.crs_godowndetail AS gd, dbo.crs_clientinstance AS ci, dbo.crs_clientlist AS cl, dbo.item AS i WHERE (((i.icode = gd.icode) AND (gd.clientinstanceid = ci.clientinstanceid)) AND (ci.clientid = cl.clientid)) GROUP BY i.icode, i.customicode, i.name, cl.name;

-- ==== view View_DB_DropBox ====
CREATE OR REPLACE VIEW dbo.view_db_dropbox AS
SELECT e.sitecode, e.targetsitecode, (SELECT s.name FROM dbo.site AS s WHERE (s.sitecode = e.sitecode)) AS sourcesite, (SELECT s.name FROM dbo.site AS s WHERE (s.sitecode = e.targetsitecode)) AS targetsite, 'S' AS documenttype, e.saleinvcode AS documentcode, a.aliasname AS aliasname, a.name AS account, CASE WHEN (e.salecatcode = 3) THEN 'Retail' ELSE 'Credit' END AS category, e.invtotal AS amount, e.date AS date, e.pushedon AS pushedon, e.pulled AS pulled, e.pulledon AS pulledon, (SELECT u.username FROM dbo.users AS u WHERE (u.usercode = e.pulledby)) AS pulledby, 'Purchase' AS respondwith, e.remarks AS remarks, e.custrefno AS refno, e.custrefno2 AS refno2, e.custrefno3 AS refno3, e.custrefno4 AS refno4, e.custrefno5 AS refno5 FROM dbo.db_saleledger AS e, dbo.accounts AS a WHERE (e.custcode = a.acccode) UNION ALL SELECT e.sitecode AS sitecode, e.targetsitecode AS targetsitecode, (SELECT s.name FROM dbo.site AS s WHERE (s.sitecode = e.sitecode)) AS sourcesite, (SELECT s.name FROM dbo.site AS s WHERE (s.sitecode = e.targetsitecode)) AS targetsite, 'SR' AS documenttype, e.srinvcode AS documentcode, a.aliasname AS aliasname, a.name AS account, CASE WHEN (e.srcatcode = 8) THEN 'Retail' ELSE 'Credit' END AS category, e.invtotal AS amount, e.date AS date, e.pushedon AS pushedon, e.pulled AS pulled, e.pulledon AS pulledon, (SELECT u.username FROM dbo.users AS u WHERE (u.usercode = e.pulledby)) AS pulledby, 'P/Return' AS respondwith, e.remarks AS remarks, e.custrefno AS refno, e.custrefno2 AS refno2, e.custrefno3 AS refno3, e.custrefno4 AS refno4, ltrim(rtrim(dbo.tsql_str((e.saleinvcode)::numeric, 100))) AS refno5 FROM dbo.db_srledger AS e, dbo.accounts AS a WHERE (e.custcode = a.acccode) UNION ALL SELECT e.sitecode AS sitecode, e.targetsitecode AS targetsitecode, (SELECT s.name FROM dbo.site AS s WHERE (s.sitecode = e.sitecode)) AS sourcesite, (SELECT s.name FROM dbo.site AS s WHERE (s.sitecode = e.targetsitecode)) AS targetsite, 'P' AS documenttype, e.purinvcode AS documentcode, a.aliasname AS aliasname, a.name AS account, CASE WHEN (e.purcatcode < 3) THEN 'Pack' WHEN (e.purcatcode = 3) THEN 'Opening' ELSE 'Loose' END AS category, e.invtotal AS amount, e.date AS date, e.pushedon AS pushedon, e.pulled AS pulled, e.pulledon AS pulledon, (SELECT u.username FROM dbo.users AS u WHERE (u.usercode = e.pulledby)) AS pulledby, 'Sales' AS respondwith, e.remarks AS remarks, e.suppinvcode AS refno, e.grn AS refno2, e.vehicle AS refno3, e.shipto AS refno4, e.lcno AS refno5 FROM dbo.db_purledger AS e, dbo.accounts AS a WHERE (e.suppcode = a.acccode) UNION ALL SELECT e.sitecode AS sitecode, e.targetsitecode AS targetsitecode, (SELECT s.name FROM dbo.site AS s WHERE (s.sitecode = e.sitecode)) AS sourcesite, (SELECT s.name FROM dbo.site AS s WHERE (s.sitecode = e.targetsitecode)) AS targetsite, 'PR' AS documenttype, e.prinvcode AS documentcode, a.aliasname AS aliasname, a.name AS account, 'Open' AS category, e.invtotal AS amount, e.date AS date, e.pushedon AS pushedon, e.pulled AS pulled, e.pulledon AS pulledon, (SELECT u.username FROM dbo.users AS u WHERE (u.usercode = e.pulledby)) AS pulledby, 'S/Return' AS respondwith, e.remarks AS remarks, e.terms1 AS refno, e.terms2 AS refno2, e.terms3 AS refno3, e.terms4 AS refno4, e.terms5 AS refno5 FROM dbo.db_prledger AS e, dbo.accounts AS a WHERE (e.suppcode = a.acccode) UNION ALL SELECT e.sitecode AS sitecode, e.targetsitecode AS targetsitecode, (SELECT s.name FROM dbo.site AS s WHERE (s.sitecode = e.sitecode)) AS sourcesite, (SELECT s.name FROM dbo.site AS s WHERE (s.sitecode = e.targetsitecode)) AS targetsite, 'IS' AS documenttype, e.issueinvcode AS documentcode, a.aliasname AS aliasname, a.name AS account, 'Issue' AS category, round(((SELECT sum((d.qty * d.price)) FROM dbo.db_issuedetail AS d WHERE ((d.sitecode = e.sitecode) AND (d.issueinvcode = e.issueinvcode))))::numeric, 2) AS amount, e.date AS date, e.pushedon AS pushedon, e.pulled AS pulled, e.pulledon AS pulledon, (SELECT u.username FROM dbo.users AS u WHERE (u.usercode = e.pulledby)) AS pulledby, e.remarks AS remarks, 'Receipt' AS respondwith, e.referenceno AS refno, e.refno2 AS refno2, e.refno3 AS refno3, e.refno4 AS refno4, e.refno5 AS refno5 FROM dbo.db_issueheader AS e, dbo.accounts AS a WHERE (e.acccode = a.acccode) UNION ALL SELECT e.sitecode AS sitecode, e.targetsitecode AS targetsitecode, (SELECT s.name FROM dbo.site AS s WHERE (s.sitecode = e.sitecode)) AS sourcesite, (SELECT s.name FROM dbo.site AS s WHERE (s.sitecode = e.targetsitecode)) AS targetsite, 'PO' AS documenttype, e.pocode AS documentcode, a.aliasname AS aliasname, a.name AS account, pc.name AS category, round(((SELECT sum((d.qty * d.rate)) FROM dbo.db_purorderdetail AS d WHERE ((d.sitecode = e.sitecode) AND (d.pocode = e.pocode))))::numeric, 2) AS amount, e.date AS date, e.pushedon AS pushedon, e.pulled AS pulled, e.pulledon AS pulledon, (SELECT u.username FROM dbo.users AS u WHERE (u.usercode = e.pulledby)) AS pulledby, 'Quotation' AS respondwith, e.remarks AS remarks, e.supplierreference AS refno, e.deliverylocation AS refno2, e.remarks AS refno3, e.remarks3 AS refno4, e.demanddraftno AS refno5 FROM dbo.db_purorderheader AS e, dbo.accounts AS a, dbo.purordercategory AS pc WHERE ((e.suppcode = a.acccode) AND (e.purordercatcode = pc.purordercatcode)) UNION ALL SELECT e.sitecode AS sitecode, e.targetsitecode AS targetsitecode, (SELECT s.name FROM dbo.site AS s WHERE (s.sitecode = e.sitecode)) AS sourcesite, (SELECT s.name FROM dbo.site AS s WHERE (s.sitecode = e.targetsitecode)) AS targetsite, 'EI' AS documenttype, e.intimationcode AS documentcode, a.aliasname AS aliasname, a.name AS account, pc.name AS category, round(((SELECT sum((d.qty * d.price)) FROM dbo.db_expiryintimationdetail AS d WHERE ((d.sitecode = e.sitecode) AND (d.intimationcode = e.intimationcode))))::numeric, 2) AS amount, e.date AS date, e.pushedon AS pushedon, e.pulled AS pulled, e.pulledon AS pulledon, (SELECT u.username FROM dbo.users AS u WHERE (u.usercode = e.pulledby)) AS pulledby, 'Intimation' AS respondwith, e.remarks1 AS remarks, e.refno AS refno, e.remarks2 AS refno2, '' AS refno3, '' AS refno4, '' AS refno5 FROM dbo.db_expiryintimation AS e, dbo.accounts AS a, dbo.intimationtype AS pc WHERE ((e.acccode = a.acccode) AND (e.intimationtypecode = pc.intimationtypecode));

-- ==== view View_ItemNotes ====
CREATE OR REPLACE VIEW dbo.view_itemnotes AS
SELECT icode, ((notes)::bytea)::text AS notes FROM dbo.itemnotes;

-- ==== view View_PrintPostDatedCheques ====
CREATE OR REPLACE VIEW dbo.view_printpostdatedcheques AS
SELECT n.notecode AS code, n.vouchercode AS vouchercode, n.issuedate AS issuedate, left(to_char(n.duedate, 'DD/MM/YYYY'), 10) AS dt, n.duedate AS duedate, n.amount AS amount, (SELECT a.name FROM dbo.accounts AS a WHERE (n.acccode = a.acccode)) AS accountname, (SELECT a.name FROM dbo.accounts AS a WHERE (n.bankacccode = a.acccode)) AS transferredto, (SELECT s.bankacc FROM dbo.supplier AS s WHERE (n.acccode = s.suppcode)) AS payeename, n.bankname AS bankname, n.documentnumber AS referenceno, n.remarks AS remarks, nc.name AS notecategory, n.posted AS posted, (SELECT u.username FROM dbo.users AS u WHERE (u.usercode = n.postedby)) AS postedby, n.postdate AS postdate, (SELECT u.username FROM dbo.users AS u WHERE (u.usercode = n.salesmancode)) AS username, n.finalized AS finalized, n.finalizeddate AS finalizeddate, (SELECT u.username FROM dbo.users AS u WHERE (u.usercode = n.finalizedby)) AS finalizedby FROM dbo.notes AS n, dbo.notescategory AS nc WHERE (n.notecatcode = nc.notecatcode);

-- ==== view VIEW_SMS_CustomerDebitIntimation ====
CREATE OR REPLACE VIEW dbo.view_sms_customerdebitintimation AS
SELECT ltrim(rtrim((cc.contactcardcode)::text)) AS contactcardcode, ltrim(rtrim((h.glvochcode)::text)) AS glvochcode, ltrim(rtrim((h.vouchercode)::text)) AS vouchercode, left(to_char(h.date, 'DD/MM/YYYY'), 10) AS date, ltrim(rtrim(dbo.tsql_str((CASE WHEN (d.debit > 0) THEN d.debit ELSE d.credit END)::numeric, 12, 2))) AS amount, ((ltrim(rtrim(dbo.tsql_str((CASE WHEN (d.balance > 0) THEN d.balance ELSE abs(d.balance) END)::numeric, 12, 2))) || ' ') || CASE WHEN (d.balance > 0) THEN 'DR' WHEN (d.balance < 0) THEN 'CR' ELSE '' END) AS previousbalance, ((ltrim(rtrim(dbo.tsql_str((CASE WHEN ((d.balance + ((d.debit - d.credit))) > 0) THEN (d.balance + ((d.debit - d.credit))) ELSE abs((d.balance + ((d.debit - d.credit)))) END)::numeric, 12, 2))) || ' ') || CASE WHEN ((d.balance + ((d.debit - d.credit))) > 0) THEN 'DR' WHEN ((d.balance + ((d.debit - d.credit))) < 0) THEN 'CR' ELSE '' END) AS newbalance, coalesce(left(to_char(h.postdate, 'DD/MM/YYYY'), 10), '') AS postdate, coalesce(ltrim(rtrim(d.chkno)), '') AS refno, coalesce(ltrim(rtrim(d.remarks)), '') AS remarks, a.name AS accountname, cc.mobile AS mobile FROM dbo.glheader AS h, dbo.gldetail AS d, dbo.accounts AS a, dbo.customer AS c, dbo.contactcard AS cc WHERE ((((((h.glvochcode = d.glvochcode) AND (d.acccode = a.acccode)) AND (a.acccode = c.custcode)) AND (d.debit > 0)) AND (a.acccode = cc.acccode)) AND (cc.useforsms = 'Y'));

-- ==== view VIEW_SMS_CustomerInstallmentReceiptAcknowledgement ====
CREATE OR REPLACE VIEW dbo.view_sms_customerinstallmentreceiptacknowledgement AS
SELECT ltrim(rtrim((cc.contactcardcode)::text)) AS contactcardcode, ltrim(rtrim((h.receiptcode)::text)) AS receiptcode, ltrim(rtrim((h.saleinvcode)::text)) AS saleinvcode, ltrim(rtrim(dbo.tsql_str((h.netamt)::numeric, 12, 2))) AS saleinvoiceamount, ltrim(rtrim(dbo.tsql_str((h.outstandingamt)::numeric, 12, 2))) AS saleinvoicebalance, left(to_char(h.date, 'DD/MM/YYYY'), 10) AS date, ltrim(rtrim(dbo.tsql_str((h.installmentamount)::numeric, 12, 2))) AS installmentamount, ltrim(rtrim(dbo.tsql_str((h.amtreceived)::numeric, 12, 2))) AS amtreceived, ltrim(rtrim(dbo.tsql_str((h.discount)::numeric, 12, 2))) AS discount, ltrim(rtrim(dbo.tsql_str((h.fine)::numeric, 12, 2))) AS fine, ltrim(rtrim(dbo.tsql_str((h.installmentbalance)::numeric, 12, 2))) AS installmentbalance, coalesce(ltrim(rtrim(h.remarks)), '') AS remarks, a.name AS customername, coalesce((SELECT sm.name FROM dbo.salesman AS sm WHERE (sm.salesmancode = h.recoverypersoncode)), '') AS recoveryperson, cc.mobile AS mobile FROM dbo.installmentreceipt AS h, dbo.saleledger AS s, dbo.accounts AS a, dbo.customer AS c, dbo.contactcard AS cc WHERE (((((((((h.amtreceived > 0) OR (h.discount > 0)) OR (h.fine > 0))) AND (h.saleinvcode = s.saleinvcode)) AND (s.custcode = c.custcode)) AND (a.acccode = c.custcode)) AND (a.acccode = cc.acccode)) AND (cc.useforsms = 'Y'));

-- ==== view VIEW_SMS_CustomerLicenseInfo ====
CREATE OR REPLACE VIEW dbo.view_sms_customerlicenseinfo AS
SELECT '1' AS contactcardcode, ltrim(rtrim((cl.licenserowid)::text)) AS code, left(to_char(cl.date, 'DD/MM/YYYY'), 10) AS date, ltrim(rtrim((a.acccode)::text)) AS acccode, coalesce(a.aliasname, '') AS aliasname, coalesce(a.name, '') AS customername, coalesce(c.cp, '') AS contactperson, coalesce(ltrim(rtrim(cl.licensekeyinput)), '') AS licensekeyinput, ((((((((substring(cl.licensekeyvalue, 1, 4) || '-') || substring(cl.licensekeyvalue, 5, 4)) || '-') || substring(cl.licensekeyvalue, 9, 4)) || '-') || substring(cl.licensekeyvalue, 13, 4)) || '-') || substring(cl.licensekeyvalue, 17, 4)) AS licensekey, coalesce(ltrim(rtrim(cl.remarks)), '') AS remarks, cl.smsto AS mobile FROM dbo.customerlicense AS cl, dbo.customerconfig AS cc, dbo.customer AS c, dbo.accounts AS a WHERE (((((cl.sendsms = 'Y') AND (length(rtrim(cl.smsto)) > 0)) AND (cl.licenseid = cc.licenseid)) AND (cc.custcode = c.custcode)) AND (c.custcode = a.acccode));

-- ==== view VIEW_SMS_CustomerReceiptAcknowledgement ====
CREATE OR REPLACE VIEW dbo.view_sms_customerreceiptacknowledgement AS
SELECT ltrim(rtrim((cc.contactcardcode)::text)) AS contactcardcode, ltrim(rtrim((h.glvochcode)::text)) AS glvochcode, ltrim(rtrim((h.vouchercode)::text)) AS vouchercode, left(to_char(h.date, 'DD/MM/YYYY'), 10) AS date, ltrim(rtrim(dbo.tsql_str((CASE WHEN (d.debit > 0) THEN d.debit ELSE d.credit END)::numeric, 12, 2))) AS amount, ((ltrim(rtrim(dbo.tsql_str((CASE WHEN (d.balance > 0) THEN d.balance ELSE abs(d.balance) END)::numeric, 12, 2))) || ' ') || CASE WHEN (d.balance > 0) THEN 'DR' WHEN (d.balance < 0) THEN 'CR' ELSE '' END) AS previousbalance, ((ltrim(rtrim(dbo.tsql_str((CASE WHEN ((d.balance + ((d.debit - d.credit))) > 0) THEN (d.balance + ((d.debit - d.credit))) ELSE abs((d.balance + ((d.debit - d.credit)))) END)::numeric, 12, 2))) || ' ') || CASE WHEN ((d.balance + ((d.debit - d.credit))) > 0) THEN 'DR' WHEN ((d.balance + ((d.debit - d.credit))) < 0) THEN 'CR' ELSE '' END) AS newbalance, coalesce(left(to_char(h.postdate, 'DD/MM/YYYY'), 10), '') AS postdate, coalesce(ltrim(rtrim(d.chkno)), '') AS refno, coalesce(ltrim(rtrim(d.remarks)), '') AS remarks, a.name AS accountname, cc.mobile AS mobile FROM dbo.glheader AS h, dbo.gldetail AS d, dbo.accounts AS a, dbo.customer AS c, dbo.contactcard AS cc WHERE (((((((h.glvochcode = d.glvochcode) AND (d.acccode = a.acccode)) AND (a.acccode = c.custcode)) AND (d.credit > 0)) AND (d.glvochcode IN (SELECT max(gd.glvochcode) FROM dbo.gldetail AS gd WHERE (((gd.glvochcode = d.glvochcode) AND (gd.debit > 0)) AND (gd.acccode IN (SELECT a.acccode FROM dbo.accounts AS a WHERE (a.subcode IN (SELECT code FROM dbo.global WHERE (name IN ('GT_CashSub', 'GT_BankSub')))))))))) AND (a.acccode = cc.acccode)) AND (cc.useforsms = 'Y'));

-- ==== view VIEW_SMS_CustomerSaleInvInfo ====
CREATE OR REPLACE VIEW dbo.view_sms_customersaleinvinfo AS
SELECT ltrim(rtrim((1)::text)) AS contactcardcode, ltrim(rtrim((h.saleinvcode)::text)) AS saleinvcode, left(to_char(h.date, 'DD/MM/YYYY'), 10) AS date, ltrim(rtrim(dbo.tsql_str((h.invtotal)::numeric, 12, 2))) AS amount, ltrim(rtrim(dbo.tsql_str((((coalesce(h.cashcharged, 0) + coalesce(h.amt, 0)) + coalesce((SELECT sum(cw.amount) FROM dbo.cashierwindow AS cw WHERE (cw.saleinvcode = h.saleinvcode)), 0)))::numeric, 12, 2))) AS collection, coalesce(left(to_char(h.duedate, 'DD/MM/YYYY'), 10), '') AS duedate, coalesce((SELECT m.description FROM dbo.message AS m WHERE (m.messagecode = h.messagecode)), '') AS message, ltrim(rtrim(dbo.tsql_str((h.custcode)::numeric, 10))) AS custcode, a.name AS customername, coalesce(h.remarks, '') AS remarks, coalesce(h.custrefno, '') AS custrefno, coalesce(h.custrefno2, '') AS custrefno2, coalesce(h.custrefno3, '') AS custrefno3, coalesce(h.custrefno4, '') AS custrefno4, coalesce(h.custrefno5, '') AS custrefno5, ltrim(rtrim((dbo.tsql_str((coalesce(abs(h.balance), 0))::numeric, 12, 2) || CASE WHEN (coalesce(h.balance, 0) >= 0) THEN '' ELSE ' Cr.' END))) AS balance, ltrim(rtrim((dbo.tsql_str((coalesce(abs(((h.balance + h.invtotal) - (((coalesce(h.cashcharged, 0) + coalesce(h.amt, 0)) + coalesce((SELECT sum(cw.amount) FROM dbo.cashierwindow AS cw WHERE (cw.saleinvcode = h.saleinvcode)), 0))))), 0))::numeric, 12, 2) || CASE WHEN (coalesce(((h.balance + h.invtotal) - (((coalesce(h.cashcharged, 0) + coalesce(h.amt, 0)) + coalesce((SELECT sum(cw.amount) FROM dbo.cashierwindow AS cw WHERE (cw.saleinvcode = h.saleinvcode)), 0)))), 0) >= 0) THEN '' ELSE ' Cr.' END))) AS newbalance, (SELECT p.regno FROM dbo.patient AS p WHERE (p.patientcode = h.patientcode)) AS patientregno, (SELECT p.name FROM dbo.patient AS p WHERE (p.patientcode = h.patientcode)) AS patientname, (SELECT g.name FROM dbo.goodscompany AS g WHERE (g.gccode = h.gccode)) AS agency, h.grn AS grn, h.vehicle AS vehicle, h.shipto AS shipto, ltrim(rtrim(dbo.tsql_str((h.previousreading)::numeric, 10, 0))) AS previousreading, ltrim(rtrim(dbo.tsql_str((h.currentreading)::numeric, 10, 0))) AS currentreading, ltrim(rtrim(dbo.tsql_str((((coalesce(h.currentreading, 0) - coalesce(h.previousreading, 0))))::numeric, 10, 0))) AS kilometers, ltrim(rtrim(dbo.tsql_str((h.nextchange)::numeric, 10, 0))) AS nextchange, c.phone AS mobile FROM dbo.saleledger AS h, dbo.customer AS c, dbo.accounts AS a WHERE (((h.custcode = c.custcode) AND (c.custcode = a.acccode)) AND (length(rtrim(c.phone)) > 0));

-- ==== view VIEW_SMS_DailyHeaderWiseNetSalesSummary ====
CREATE OR REPLACE VIEW dbo.view_sms_dailyheaderwisenetsalessummary AS
SELECT '-1' AS contactcardcode, left(to_char(t.date, 'DD/MM/YYYY'), 100) AS date, '1' AS code, (SELECT dbo.fn_getheaderwisesalesummary(t.date) AS rep) AS report, '' AS mobile FROM (SELECT localtimestamp(3) AS date) AS t;

-- ==== view VIEW_SMS_DailySalesAndReturnSummary ====
CREATE OR REPLACE VIEW dbo.view_sms_dailysalesandreturnsummary AS
SELECT '-1' AS contactcardcode, left(to_char(localtimestamp(3), 'DD/MM/YYYY'), 100) AS date, '1' AS code, ltrim(rtrim((sum(sales))::text)) AS totalsales, ltrim(rtrim((sum(invcount))::text)) AS saleinvoices, ltrim(rtrim((sum(sr))::text)) AS salesreturn, ltrim(rtrim((sum(srcount))::text)) AS salereturninvoices, ltrim(rtrim((sum((sales - sr)))::text)) AS netsales, ltrim(rtrim(dbo.tsql_str((sum(cost))::numeric, 15, 2))) AS cgs, ltrim(rtrim(dbo.tsql_str((round((sum(((sales - sr) - cost)))::numeric, 2))::numeric, 15, 2))) AS grossprofit, ltrim(rtrim(dbo.tsql_str((round((((round((sum(((sales - sr) - cost)))::numeric, 2) / CASE WHEN (sum((sales - sr)) = 0) THEN 1 ELSE sum((sales - sr)) END) * 100))::numeric, 2))::numeric, 15, 2))) AS gprate, '' AS mobile FROM (SELECT coalesce(sum(h.invtotal), 0) AS sales, count(h.saleinvcode) AS invcount, 0 AS sr, 0 AS srcount, 0 AS cost FROM dbo.saleledger AS h WHERE ((left(to_char(h.date, 'DD/MM/YYYY'), 100))::citext = (left(to_char(localtimestamp(3), 'DD/MM/YYYY'), 100))::citext) UNION SELECT 0 AS sales, 0 AS invcount, coalesce(sum(h.invtotal), 0) AS sr, count(h.srinvcode) AS srcount, 0 AS cost FROM dbo.srledger AS h WHERE ((left(to_char(h.date, 'DD/MM/YYYY'), 100))::citext = (left(to_char(localtimestamp(3), 'DD/MM/YYYY'), 100))::citext) UNION SELECT 0 AS sales, 0 AS invcount, 0 AS sr, 0 AS srcount, round((sum((((d.looseqty + d.bonusqty)) * d.avgprice)))::numeric, 2) AS cost FROM dbo.saleledger AS h, dbo.saledetail AS d WHERE (((left(to_char(h.date, 'DD/MM/YYYY'), 100))::citext = (left(to_char(localtimestamp(3), 'DD/MM/YYYY'), 100))::citext) AND (h.saleinvcode = d.saleinvcode)) UNION SELECT 0 AS sales, 0 AS invcount, 0 AS sr, 0 AS srcount, (-round((sum((((d.looseqty + d.bonusqty)) * d.avgprice)))::numeric, 2)) AS cost FROM dbo.srledger AS h, dbo.srdetail AS d WHERE (((left(to_char(h.date, 'DD/MM/YYYY'), 100))::citext = (left(to_char(localtimestamp(3), 'DD/MM/YYYY'), 100))::citext) AND (h.srinvcode = d.srinvcode))) AS t;

-- ==== view VIEW_SMS_ManufacturerMonthlyNetSaleToDate ====
CREATE OR REPLACE VIEW dbo.view_sms_manufacturermonthlynetsaletodate AS
SELECT '-1' AS contactcardcode, left(to_char(t.date, 'DD/MM/YYYY'), 100) AS date, '1' AS code, (SELECT dbo.fn_getmanfwisenetsaletodate(t.date) AS rep) AS report, '' AS mobile FROM (SELECT localtimestamp(3) AS date) AS t;

-- ==== view VIEW_SMS_PatientAdmissionInfo ====
CREATE OR REPLACE VIEW dbo.view_sms_patientadmissioninfo AS
SELECT ltrim(rtrim((-1)::text)) AS contactcardcode, ltrim(rtrim((pa.admissioncode)::text)) AS admissioncode, left(to_char(pa.date, 'DD/MM/YYYY'), 10) AS date, ltrim(rtrim(left(to_char(pa.date, 'HH24:MI:SS'), 20))) AS admissiontime, p.regno AS patientregno, p.name AS patientname, coalesce((SELECT a.name FROM dbo.accounts AS a WHERE (a.acccode = p.custcode)), '') AS customer, coalesce((SELECT d.name FROM dbo.doctors AS d WHERE (d.doctcode = pa.doctorcode)), '') AS doctor, ltrim(rtrim(dbo.tsql_str((pa.cashcharged)::numeric, 12, 2))) AS cashcharged, coalesce((SELECT l.name FROM dbo.patientlocation AS l WHERE (l.locationcode = pa.locationcode)), '') AS location, coalesce((SELECT d.name FROM dbo.disease AS d WHERE (d.diseasecode = pa.diseasecode)), '') AS disease, coalesce(pa.diagnosis, '') AS diagnosis, coalesce(pa.remarks, '') AS remarks, ((coalesce(p.mobileno1, '') || CASE WHEN ((coalesce(p.mobileno1, ''))::citext = '') THEN '' ELSE ',' END) || coalesce((SELECT d.phone FROM dbo.doctors AS d WHERE (d.doctcode = pa.doctorcode)), '')) AS mobile FROM dbo.patientadmission AS pa, dbo.patient AS p WHERE (((pa.discharged1 = 'N') AND (pa.discharged = 'N')) AND (pa.patientcode = p.patientcode));

-- ==== view VIEW_SMS_PatientDischargeInfo ====
CREATE OR REPLACE VIEW dbo.view_sms_patientdischargeinfo AS
SELECT ltrim(rtrim((-1)::text)) AS contactcardcode, ltrim(rtrim((pa.admissioncode)::text)) AS admissioncode, left(to_char(pa.date, 'DD/MM/YYYY'), 10) AS admissiondate, ltrim(rtrim(left(to_char(pa.date, 'HH24:MI:SS'), 20))) AS admissiontime, left(to_char(pa.dischargedon, 'DD/MM/YYYY'), 10) AS dischargedate, ltrim(rtrim(left(to_char(pa.dischargedon, 'HH24:MI:SS'), 20))) AS dischargetime, p.regno AS patientregno, p.name AS patientname, coalesce((SELECT a.name FROM dbo.accounts AS a WHERE (a.acccode = p.custcode)), '') AS customer, coalesce((SELECT d.name FROM dbo.doctors AS d WHERE (d.doctcode = pa.doctorcode)), '') AS doctor, ltrim(rtrim(dbo.tsql_str((pa.cashcharged)::numeric, 12, 2))) AS cashcharged, coalesce((SELECT l.name FROM dbo.patientlocation AS l WHERE (l.locationcode = pa.locationcode)), '') AS location, coalesce((SELECT d.name FROM dbo.disease AS d WHERE (d.diseasecode = pa.diseasecode)), '') AS disease, coalesce(pa.diagnosis, '') AS diagnosis, coalesce(pa.remarks, '') AS remarks, coalesce(pa.dischargenotes, '') AS dischargenotes, ((coalesce(p.mobileno1, '') || CASE WHEN ((coalesce(p.mobileno1, ''))::citext = '') THEN '' ELSE ',' END) || coalesce((SELECT d.phone FROM dbo.doctors AS d WHERE (d.doctcode = pa.doctorcode)), '')) AS mobile FROM dbo.patientadmission AS pa, dbo.patient AS p WHERE (((pa.discharged1 = 'Y') AND (pa.discharged = 'Y')) AND (pa.patientcode = p.patientcode));

-- ==== view VIEW_SMS_PatientRegistrationInfo ====
CREATE OR REPLACE VIEW dbo.view_sms_patientregistrationinfo AS
SELECT ltrim(rtrim((-1)::text)) AS contactcardcode, ltrim(rtrim((p.patientcode)::text)) AS patientcode, left(to_char(p.date, 'DD/MM/YYYY'), 10) AS registrationdate, ltrim(rtrim(left(to_char(p.date, 'HH24:MI:SS'), 20))) AS registrationtime, p.regno AS patientregno, p.name AS patientname, coalesce((SELECT a.name FROM dbo.accounts AS a WHERE (a.acccode = p.custcode)), '') AS customer, coalesce((SELECT d.name FROM dbo.doctors AS d WHERE (d.doctcode = p.doctcode)), '') AS doctor, ltrim(rtrim(dbo.tsql_str((p.cashcharged)::numeric, 12, 2))) AS cashcharged, coalesce((SELECT l.name FROM dbo.patientlocation AS l WHERE (l.locationcode = p.locationcode)), '') AS location, coalesce((SELECT d.name FROM dbo.disease AS d WHERE (d.diseasecode = p.diseasecode)), '') AS disease, coalesce(p.diagnosis, '') AS diagnosis, coalesce(p.gender, '') AS gender, coalesce(p.nationalidcard, '') AS nic, coalesce(p.ward, '') AS ward, coalesce(p.refno1, '') AS refno1, coalesce(p.refno2, '') AS refno2, coalesce(p.refno3, '') AS refno3, coalesce(p.refno4, '') AS refno4, coalesce(p.refno5, '') AS refno5, coalesce(p.refno6, '') AS refno6, coalesce(p.refno7, '') AS refno7, ((coalesce(p.mobileno1, '') || CASE WHEN ((coalesce(p.mobileno1, ''))::citext = '') THEN '' ELSE ',' END) || coalesce((SELECT d.phone FROM dbo.doctors AS d WHERE (d.doctcode = p.doctcode)), '')) AS mobile FROM dbo.patient AS p;

-- ==== view VIEW_SMS_PatientSaleInvInfo ====
CREATE OR REPLACE VIEW dbo.view_sms_patientsaleinvinfo AS
SELECT ltrim(rtrim((-1)::text)) AS contactcardcode, ltrim(rtrim((h.saleinvcode)::text)) AS saleinvcode, left(to_char(h.date, 'DD/MM/YYYY'), 10) AS date, ltrim(rtrim(dbo.tsql_str((h.invtotal)::numeric, 12, 2))) AS amount, ltrim(rtrim(dbo.tsql_str((((coalesce(h.cashcharged, 0) + coalesce(h.amt, 0)) + coalesce((SELECT sum(cw.amount) FROM dbo.cashierwindow AS cw WHERE (cw.saleinvcode = h.saleinvcode)), 0)))::numeric, 12, 2))) AS collection, coalesce(left(to_char(h.duedate, 'DD/MM/YYYY'), 10), '') AS duedate, coalesce((SELECT m.description FROM dbo.message AS m WHERE (m.messagecode = h.messagecode)), '') AS message, ltrim(rtrim(dbo.tsql_str((h.custcode)::numeric, 10))) AS custcode, a.name AS customername, coalesce(h.remarks, '') AS remarks, coalesce(h.custrefno, '') AS custrefno, coalesce(h.custrefno2, '') AS custrefno2, coalesce(h.custrefno3, '') AS custrefno3, coalesce(h.custrefno4, '') AS custrefno4, coalesce(h.custrefno5, '') AS custrefno5, ltrim(rtrim((dbo.tsql_str((coalesce(abs(h.balance), 0))::numeric, 12, 2) || CASE WHEN (coalesce(h.balance, 0) >= 0) THEN '' ELSE ' Cr.' END))) AS balance, ltrim(rtrim((dbo.tsql_str((coalesce(abs(((h.balance + h.invtotal) - (((coalesce(h.cashcharged, 0) + coalesce(h.amt, 0)) + coalesce((SELECT sum(cw.amount) FROM dbo.cashierwindow AS cw WHERE (cw.saleinvcode = h.saleinvcode)), 0))))), 0))::numeric, 12, 2) || CASE WHEN (coalesce(((h.balance + h.invtotal) - (((coalesce(h.cashcharged, 0) + coalesce(h.amt, 0)) + coalesce((SELECT sum(cw.amount) FROM dbo.cashierwindow AS cw WHERE (cw.saleinvcode = h.saleinvcode)), 0)))), 0) >= 0) THEN '' ELSE ' Cr.' END))) AS newbalance, (SELECT p.regno FROM dbo.patient AS p WHERE (p.patientcode = h.patientcode)) AS patientregno, (SELECT p.name FROM dbo.patient AS p WHERE (p.patientcode = h.patientcode)) AS patientname, (SELECT g.name FROM dbo.goodscompany AS g WHERE (g.gccode = h.gccode)) AS agency, h.grn AS grn, h.vehicle AS vehicle, h.shipto AS shipto, ltrim(rtrim(dbo.tsql_str((h.previousreading)::numeric, 10, 0))) AS previousreading, ltrim(rtrim(dbo.tsql_str((h.currentreading)::numeric, 10, 0))) AS currentreading, ltrim(rtrim(dbo.tsql_str((((coalesce(h.currentreading, 0) - coalesce(h.previousreading, 0))))::numeric, 10, 0))) AS kilometers, ltrim(rtrim(dbo.tsql_str((h.nextchange)::numeric, 10, 0))) AS nextchange, (SELECT p.mobileno1 FROM dbo.patient AS p WHERE (p.patientcode = h.patientcode)) AS mobile FROM dbo.saleledger AS h, dbo.customer AS c, dbo.accounts AS a WHERE ((h.custcode = c.custcode) AND (c.custcode = a.acccode));

