CREATE OR REPLACE VIEW dbo.view_sms_saleinvinfo AS
SELECT ltrim(rtrim((cc.contactcardcode)::text)) AS contactcardcode, ltrim(rtrim((h.saleinvcode)::text)) AS saleinvcode, left(to_char(h.date, 'DD/MM/YYYY'), 10) AS date, ltrim(rtrim(dbo.tsql_str((h.invtotal)::numeric, 12, 2))) AS amount, ltrim(rtrim(dbo.tsql_str((((coalesce(h.cashcharged, 0) + coalesce(h.amt, 0)) + coalesce((SELECT sum(cw.amount) FROM dbo.cashierwindow AS cw WHERE (cw.saleinvcode = h.saleinvcode)), 0)))::numeric, 12, 2))) AS collection, coalesce(left(to_char(h.duedate, 'DD/MM/YYYY'), 10), '') AS duedate, coalesce((SELECT m.description FROM dbo.message AS m WHERE (m.messagecode = h.messagecode)), '') AS message, ltrim(rtrim(dbo.tsql_str((h.custcode)::numeric, 10))) AS custcode, a.name AS customername, coalesce(h.remarks, '') AS remarks, coalesce(h.custrefno, '') AS custrefno, coalesce(h.custrefno2, '') AS custrefno2, coalesce(h.custrefno3, '') AS custrefno3, coalesce(h.custrefno4, '') AS custrefno4, coalesce(h.custrefno5, '') AS custrefno5, ltrim(rtrim((dbo.tsql_str((coalesce(abs(h.balance), 0))::numeric, 12, 2) || CASE WHEN (coalesce(h.balance, 0) >= 0) THEN '' ELSE ' Cr.' END))) AS balance, ltrim(rtrim((dbo.tsql_str((coalesce(abs(((h.balance + h.invtotal) - (((coalesce(h.cashcharged, 0) + coalesce(h.amt, 0)) + coalesce((SELECT sum(cw.amount) FROM dbo.cashierwindow AS cw WHERE (cw.saleinvcode = h.saleinvcode)), 0))))), 0))::numeric, 12, 2) || CASE WHEN (coalesce(((h.balance + h.invtotal) - (((coalesce(h.cashcharged, 0) + coalesce(h.amt, 0)) + coalesce((SELECT sum(cw.amount) FROM dbo.cashierwindow AS cw WHERE (cw.saleinvcode = h.saleinvcode)), 0)))), 0) >= 0) THEN '' ELSE ' Cr.' END))) AS newbalance, (SELECT p.regno FROM dbo.patient AS p WHERE (p.patientcode = h.patientcode)) AS patientregno, (SELECT p.name FROM dbo.patient AS p WHERE (p.patientcode = h.patientcode)) AS patientname, (SELECT g.name FROM dbo.goodscompany AS g WHERE (g.gccode = h.gccode)) AS agency, h.grn AS grn, h.vehicle AS vehicle, h.shipto AS shipto, ltrim(rtrim(dbo.tsql_str((h.previousreading)::numeric, 10, 0))) AS previousreading, ltrim(rtrim(dbo.tsql_str((h.currentreading)::numeric, 10, 0))) AS currentreading, ltrim(rtrim(dbo.tsql_str((((coalesce(h.currentreading, 0) - coalesce(h.previousreading, 0))))::numeric, 10, 0))) AS kilometers, ltrim(rtrim(dbo.tsql_str((h.nextchange)::numeric, 10, 0))) AS nextchange, cc.mobile AS mobile FROM dbo.saleledger AS h, dbo.customer AS c, dbo.accounts AS a, dbo.contactcard AS cc WHERE ((((h.custcode = c.custcode) AND (c.custcode = a.acccode)) AND (a.acccode = cc.acccode)) AND (cc.useforsms = 'Y'));

-- ==== view VIEW_SMS_SaleInvInfo2 ====
CREATE OR REPLACE VIEW dbo.view_sms_saleinvinfo2 AS
SELECT ltrim(rtrim((cc.contactcardcode)::text)) AS contactcardcode, ltrim(rtrim((h.saleinvcode)::text)) AS saleinvcode, left(to_char(h.date, 'DD/MM/YYYY'), 10) AS date, ltrim(rtrim(dbo.tsql_str((h.invtotal)::numeric, 12, 2))) AS amount, ltrim(rtrim(dbo.tsql_str((((coalesce(h.cashcharged, 0) + coalesce(h.amt, 0)) + coalesce((SELECT sum(cw.amount) FROM dbo.cashierwindow AS cw WHERE (cw.saleinvcode = h.saleinvcode)), 0)))::numeric, 12, 2))) AS collection, coalesce(left(to_char(h.duedate, 'DD/MM/YYYY'), 10), '') AS duedate, coalesce((SELECT m.description FROM dbo.message AS m WHERE (m.messagecode = h.messagecode)), '') AS message, ltrim(rtrim(dbo.tsql_str((h.custcode)::numeric, 10))) AS custcode, ltrim(rtrim(((coalesce(cc.title, '') || ' ') || cc.name))) AS customername, coalesce(h.remarks, '') AS remarks, coalesce(h.custrefno, '') AS custrefno, coalesce(h.custrefno2, '') AS custrefno2, coalesce(h.custrefno3, '') AS custrefno3, coalesce(h.custrefno4, '') AS custrefno4, coalesce(h.custrefno5, '') AS custrefno5, ltrim(rtrim((dbo.tsql_str((coalesce(abs(h.balance), 0))::numeric, 12, 2) || CASE WHEN (coalesce(h.balance, 0) >= 0) THEN '' ELSE ' Cr.' END))) AS balance, ltrim(rtrim((dbo.tsql_str((coalesce(abs(((h.balance + h.invtotal) - (((coalesce(h.cashcharged, 0) + coalesce(h.amt, 0)) + coalesce((SELECT sum(cw.amount) FROM dbo.cashierwindow AS cw WHERE (cw.saleinvcode = h.saleinvcode)), 0))))), 0))::numeric, 12, 2) || CASE WHEN (coalesce(((h.balance + h.invtotal) - (((coalesce(h.cashcharged, 0) + coalesce(h.amt, 0)) + coalesce((SELECT sum(cw.amount) FROM dbo.cashierwindow AS cw WHERE (cw.saleinvcode = h.saleinvcode)), 0)))), 0) >= 0) THEN '' ELSE ' Cr.' END))) AS newbalance, coalesce((SELECT p.regno FROM dbo.patient AS p WHERE (p.patientcode = h.patientcode)), '') AS patientregno, coalesce((SELECT p.name FROM dbo.patient AS p WHERE (p.patientcode = h.patientcode)), '') AS patientname, coalesce((SELECT g.name FROM dbo.goodscompany AS g WHERE (g.gccode = h.gccode)), '') AS agency, coalesce(h.grn, '') AS grn, coalesce(h.vehicle, '') AS vehicle, coalesce(h.shipto, '') AS shipto, ltrim(rtrim(dbo.tsql_str((h.previousreading)::numeric, 10, 0))) AS previousreading, ltrim(rtrim(dbo.tsql_str((h.currentreading)::numeric, 10, 0))) AS currentreading, ltrim(rtrim(dbo.tsql_str((((coalesce(h.currentreading, 0) - coalesce(h.previousreading, 0))))::numeric, 10, 0))) AS kilometers, ltrim(rtrim(dbo.tsql_str((h.nextchange)::numeric, 10, 0))) AS nextchange, cc.mobile AS mobile FROM dbo.saleledger AS h, dbo.contactcard AS cc WHERE (((h.contactcardcode IS NOT NULL) AND (h.contactcardcode = cc.contactcardcode)) AND (cc.useforsms = 'Y'));

-- ==== view VIEW_SMS_SaleOrderInfo ====
CREATE OR REPLACE VIEW dbo.view_sms_saleorderinfo AS
SELECT ltrim(rtrim((cc.contactcardcode)::text)) AS contactcardcode, ltrim(rtrim((h.saleordercode)::text)) AS saleordercode, left(to_char(h.date, 'DD/MM/YYYY'), 10) AS date, ltrim(rtrim(dbo.tsql_str((h.invtotal)::numeric, 12, 2))) AS amount, coalesce(left(to_char(h.deliverydeadline, 'DD/MM/YYYY'), 10), '') AS deliverydeadline, coalesce((SELECT m.description FROM dbo.message AS m WHERE (m.messagecode = h.messagecode)), '') AS message, ltrim(rtrim(dbo.tsql_str((h.custcode)::numeric, 10))) AS custcode, a.name AS customername, coalesce(h.remarks, '') AS remarks, coalesce(h.custrefno, '') AS custrefno, coalesce(h.custrefno2, '') AS custrefno2, coalesce(h.custrefno3, '') AS custrefno3, coalesce(h.custrefno4, '') AS custrefno4, cc.mobile AS mobile FROM dbo.saleorderheader AS h, dbo.customer AS c, dbo.accounts AS a, dbo.contactcard AS cc WHERE ((((h.custcode = c.custcode) AND (c.custcode = a.acccode)) AND (a.acccode = cc.acccode)) AND (cc.useforsms = 'Y'));

-- ==== view VIEW_SMS_ServiceInvInfo ====
CREATE OR REPLACE VIEW dbo.view_sms_serviceinvinfo AS
SELECT ltrim(rtrim((cc.contactcardcode)::text)) AS contactcardcode, ltrim(rtrim((h.serviceinvcode)::text)) AS serviceinvcode, left(to_char(h.date, 'DD/MM/YYYY'), 10) AS date, ltrim(rtrim(dbo.tsql_str((h.invtotal)::numeric, 12, 2))) AS amount, ltrim(rtrim(dbo.tsql_str(((coalesce(h.cashcharged, 0) + coalesce((SELECT sum(cw.amount) FROM dbo.mastercashwin AS cw WHERE ((cw.documenttype = 'RS') AND (cw.documentcode = h.serviceinvcode))), 0)))::numeric, 12, 2))) AS collection, ltrim(rtrim(dbo.tsql_str((h.outstandingamt)::numeric, 12, 2))) AS outstandingamount, coalesce(left(to_char(h.duedate, 'DD/MM/YYYY'), 10), '') AS duedate, ltrim(rtrim(dbo.tsql_str((h.custcode)::numeric, 10))) AS custcode, a.name AS customername, coalesce(h.remarks, '') AS remarks, coalesce(h.ref1, '') AS ref1, coalesce(h.ref2, '') AS ref2, cc.mobile AS mobile FROM dbo.serviceheader AS h, dbo.customer AS c, dbo.accounts AS a, dbo.contactcard AS cc WHERE ((((h.custcode = c.custcode) AND (c.custcode = a.acccode)) AND (a.acccode = cc.acccode)) AND (cc.useforsms = 'Y'));

-- ==== view VIEW_SMS_ServiceInvPatientInfo ====
CREATE OR REPLACE VIEW dbo.view_sms_serviceinvpatientinfo AS
SELECT ltrim(rtrim((-1)::text)) AS contactcardcode, ltrim(rtrim((h.serviceinvcode)::text)) AS serviceinvcode, left(to_char(h.date, 'DD/MM/YYYY'), 10) AS date, ltrim(rtrim(dbo.tsql_str((h.invtotal)::numeric, 12, 2))) AS amount, ltrim(rtrim(dbo.tsql_str(((coalesce(h.cashcharged, 0) + coalesce((SELECT sum(cw.amount) FROM dbo.mastercashwin AS cw WHERE ((cw.documenttype = 'RS') AND (cw.documentcode = h.serviceinvcode))), 0)))::numeric, 12, 2))) AS collection, ltrim(rtrim(dbo.tsql_str((h.outstandingamt)::numeric, 12, 2))) AS outstandingamount, coalesce(left(to_char(h.duedate, 'DD/MM/YYYY'), 10), '') AS duedate, ltrim(rtrim(dbo.tsql_str((h.custcode)::numeric, 10))) AS custcode, a.name AS customername, p.regno AS patientregno, p.name AS patient, coalesce(h.remarks, '') AS remarks, coalesce(h.ref1, '') AS ref1, coalesce(h.ref2, '') AS ref2, p.mobileno1 AS mobile FROM dbo.serviceheader AS h, dbo.customer AS c, dbo.accounts AS a, dbo.patient AS p WHERE ((((h.custcode = c.custcode) AND (c.custcode = a.acccode)) AND (h.patientcode = p.patientcode)) AND (length(rtrim(p.mobileno1)) >= 10));

-- ==== view VIEW_SMS_SupplierCreditIntimation ====
CREATE OR REPLACE VIEW dbo.view_sms_suppliercreditintimation AS
SELECT ltrim(rtrim((cc.contactcardcode)::text)) AS contactcardcode, ltrim(rtrim((h.glvochcode)::text)) AS glvochcode, ltrim(rtrim((h.vouchercode)::text)) AS vouchercode, left(to_char(h.date, 'DD/MM/YYYY'), 10) AS date, ltrim(rtrim(dbo.tsql_str((CASE WHEN (d.debit > 0) THEN d.debit ELSE d.credit END)::numeric, 12, 2))) AS amount, ((ltrim(rtrim(dbo.tsql_str((CASE WHEN (d.balance > 0) THEN d.balance ELSE abs(d.balance) END)::numeric, 12, 2))) || ' ') || CASE WHEN (d.balance > 0) THEN 'DR' WHEN (d.balance < 0) THEN 'CR' ELSE '' END) AS previousbalance, ((ltrim(rtrim(dbo.tsql_str((CASE WHEN ((d.balance + ((d.debit - d.credit))) > 0) THEN (d.balance + ((d.debit - d.credit))) ELSE abs((d.balance + ((d.debit - d.credit)))) END)::numeric, 12, 2))) || ' ') || CASE WHEN ((d.balance + ((d.debit - d.credit))) > 0) THEN 'DR' WHEN ((d.balance + ((d.debit - d.credit))) < 0) THEN 'CR' ELSE '' END) AS newbalance, coalesce(left(to_char(h.postdate, 'DD/MM/YYYY'), 10), '') AS postdate, coalesce(ltrim(rtrim(d.chkno)), '') AS refno, coalesce(ltrim(rtrim(d.remarks)), '') AS remarks, a.name AS accountname, cc.mobile AS mobile FROM dbo.glheader AS h, dbo.gldetail AS d, dbo.accounts AS a, dbo.supplier AS s, dbo.contactcard AS cc WHERE ((((((h.glvochcode = d.glvochcode) AND (d.acccode = a.acccode)) AND (a.acccode = s.suppcode)) AND (d.credit > 0)) AND (a.acccode = cc.acccode)) AND (cc.useforsms = 'Y'));

-- ==== view VIEW_SMS_SupplierPaymentInfo ====
CREATE OR REPLACE VIEW dbo.view_sms_supplierpaymentinfo AS
SELECT ltrim(rtrim((cc.contactcardcode)::text)) AS contactcardcode, ltrim(rtrim((h.glvochcode)::text)) AS glvochcode, ltrim(rtrim((h.vouchercode)::text)) AS vouchercode, left(to_char(h.date, 'DD/MM/YYYY'), 10) AS date, ltrim(rtrim(dbo.tsql_str((CASE WHEN (d.debit > 0) THEN d.debit ELSE d.credit END)::numeric, 12, 2))) AS amount, ((ltrim(rtrim(dbo.tsql_str((CASE WHEN (d.balance > 0) THEN d.balance ELSE abs(d.balance) END)::numeric, 12, 2))) || ' ') || CASE WHEN (d.balance > 0) THEN 'DR' WHEN (d.balance < 0) THEN 'CR' ELSE '' END) AS previousbalance, ((ltrim(rtrim(dbo.tsql_str((CASE WHEN ((d.balance + ((d.debit - d.credit))) > 0) THEN (d.balance + ((d.debit - d.credit))) ELSE abs((d.balance + ((d.debit - d.credit)))) END)::numeric, 12, 2))) || ' ') || CASE WHEN ((d.balance + ((d.debit - d.credit))) > 0) THEN 'DR' WHEN ((d.balance + ((d.debit - d.credit))) < 0) THEN 'CR' ELSE '' END) AS newbalance, coalesce(left(to_char(h.postdate, 'DD/MM/YYYY'), 10), '') AS postdate, coalesce(ltrim(rtrim(d.chkno)), '') AS refno, coalesce(ltrim(rtrim(d.remarks)), '') AS remarks, a.name AS accountname, cc.mobile AS mobile FROM dbo.glheader AS h, dbo.gldetail AS d, dbo.accounts AS a, dbo.supplier AS s, dbo.contactcard AS cc WHERE (((((((h.glvochcode = d.glvochcode) AND (d.acccode = a.acccode)) AND (a.acccode = s.suppcode)) AND (d.debit > 0)) AND (d.glvochcode IN (SELECT max(gd.glvochcode) FROM dbo.gldetail AS gd WHERE (((gd.glvochcode = d.glvochcode) AND (gd.credit > 0)) AND (gd.acccode IN (SELECT a.acccode FROM dbo.accounts AS a WHERE (a.subcode IN (SELECT code FROM dbo.global WHERE (name IN ('GT_CashSub', 'GT_BankSub')))))))))) AND (a.acccode = cc.acccode)) AND (cc.useforsms = 'Y'));

-- ==== view VIEW_SMS_TotalServicesInfo ====
CREATE OR REPLACE VIEW dbo.view_sms_totalservicesinfo AS
SELECT '-1' AS contactcardcode, ltrim(rtrim((1)::text)) AS code, coalesce(left(to_char(localtimestamp(3), 'DD/MM/YYYY'), 10), '') AS date, ltrim(rtrim(dbo.tsql_str((coalesce(sum(h.invtotal), 0))::numeric, 12, 2))) AS servicerevenue, ltrim(rtrim(dbo.tsql_str(((coalesce(sum(h.cashcharged), 0) + coalesce((SELECT sum(cw.amount) FROM dbo.mastercashwin AS cw WHERE ((cw.documenttype = 'RS') AND (cw.documentcode IN (SELECT s.serviceinvcode FROM dbo.serviceheader AS s WHERE ((left(to_char(s.date, 'DD/MM/YYYY'), 10))::citext = (left(to_char(localtimestamp(3), 'DD/MM/YYYY'), 10))::citext))))), 0)))::numeric, 12, 2))) AS collection, ltrim(rtrim(dbo.tsql_str((coalesce(sum(h.outstandingamt), 0))::numeric, 12, 2))) AS outstandingamount, '' AS mobile FROM dbo.serviceheader AS h WHERE ((left(to_char(h.date, 'DD/MM/YYYY'), 10))::citext = (left(to_char(localtimestamp(3), 'DD/MM/YYYY'), 10))::citext);

-- ==== view VIEW_SMS_VisitAppointmentInfo ====
CREATE OR REPLACE VIEW dbo.view_sms_visitappointmentinfo AS
SELECT ltrim(rtrim((-1)::text)) AS contactcardcode, ltrim(rtrim((v.appointmentcode)::text)) AS appointmentcode, left(to_char(v.date, 'DD/MM/YYYY'), 10) AS bookingdate, ltrim(rtrim(left(to_char(v.date, 'HH24:MI:SS'), 20))) AS bookingtime, left(to_char(v.duedate, 'DD/MM/YYYY'), 10) AS appointmentdate, ltrim(rtrim(left(to_char(v.duedate, 'HH24:MI:SS'), 20))) AS appointmenttime, p.regno AS patientregno, p.name AS patientname, coalesce((SELECT a.name FROM dbo.accounts AS a WHERE (a.acccode = p.custcode)), '') AS customer, coalesce((SELECT d.name FROM dbo.doctors AS d WHERE (d.doctcode = v.doctcode)), '') AS doctor, ltrim(rtrim(dbo.tsql_str((v.tokenno)::numeric, 12))) AS tokenno, coalesce((SELECT m.name FROM dbo.appointmentmethod AS m WHERE (m.appointmentmethodcode = v.appointmentmethodcode)), '') AS appointmentmethod, coalesce((SELECT s.name FROM dbo.appointmentstatus AS s WHERE (s.appointmentstatuscode = v.appointmentstatuscode)), '') AS appointmentstatus, coalesce(v.remarks, '') AS remarks, coalesce(v.referredby, '') AS referredby, coalesce(v.comments, '') AS comments, ((coalesce(p.mobileno1, '') || CASE WHEN ((coalesce(p.mobileno1, ''))::citext = '') THEN '' ELSE ',' END) || coalesce((SELECT d.phone FROM dbo.doctors AS d WHERE (d.doctcode = v.doctcode)), '')) AS mobile FROM dbo.visitappointment AS v, dbo.patient AS p WHERE (v.patientcode = p.patientcode);

-- ==== view VIEW_SMS_ZonalSaleAndStock_CatWise_ToDate ====
CREATE OR REPLACE VIEW dbo.view_sms_zonalsaleandstock_catwise_todate AS
SELECT t.* FROM (SELECT ltrim(rtrim((cc.contactcardcode)::text)) AS contactcardcode, left(to_char(t.date, 'DD/MM/YYYY'), 100) AS date, '1' AS code, (SELECT dbo.fn_get_zonalsaleandstock_catwise_todate(z.zonecode, t.date) AS rep) AS report, cc.mobile AS mobile FROM (SELECT localtimestamp(3) AS date) AS t, dbo.zone AS z, dbo.zonecontactgroup AS zcg, dbo.contactgroup AS cg, dbo.contactgroupdetail AS cgd, dbo.contactcard AS cc WHERE ((((((z.useforsms = 'Y') AND (z.zonecode = zcg.zonecode)) AND (zcg.contactgroupcode = cg.contactgroupcode)) AND (cg.contactgroupcode = cgd.contactgroupcode)) AND (cgd.contactcardcode = cc.contactcardcode)) AND (cc.useforsms = 'Y'))) AS t WHERE ((report IS NOT NULL) AND (report <> ''));

-- ==== view VIEW_SMS_Zone_SaleAndStock_CatWise_ToDate ====
CREATE OR REPLACE VIEW dbo.view_sms_zone_saleandstock_catwise_todate AS
SELECT t.* FROM (SELECT ltrim(rtrim((cc.contactcardcode)::text)) AS contactcardcode, left(to_char(t.date, 'DD/MM/YYYY'), 100) AS date, '1' AS code, ltrim(rtrim(dbo.tsql_str((z.zonecode)::numeric, 5, 0))) AS zonecode, (SELECT dbo.fn_get_zonalsaleandstock_catwise_todate(z.zonecode, t.date) AS rep) AS report, cc.mobile AS mobile FROM (SELECT localtimestamp(3) AS date) AS t, dbo.zone AS z, dbo.zonecontactgroup AS zcg, dbo.contactgroup AS cg, dbo.contactgroupdetail AS cgd, dbo.contactcard AS cc WHERE ((((((z.useforsms = 'Y') AND (z.zonecode = zcg.zonecode)) AND (zcg.contactgroupcode = cg.contactgroupcode)) AND (cg.contactgroupcode = cgd.contactgroupcode)) AND (cgd.contactcardcode = cc.contactcardcode)) AND (cc.useforsms = 'Y'))) AS t WHERE ((report IS NOT NULL) AND (report <> ''));

-- ==== view VIEW_WaseelaMini_Customer ====
CREATE OR REPLACE VIEW dbo.view_waseelamini_customer AS
SELECT c.custcode AS custcode, a.aliasname AS aliasname, a.name AS customername, cc.name AS customercategory, c.cp AS contactperson, c.cp2 AS contactperson2, c.address1 AS address1, c.address2 AS address2, c.city AS city, c.country AS country, c.cellno AS cellno, c.phone AS phone, c.fax AS fax, c.email AS email, c.crlimit AS creditlimit, c.dayslimit AS dayslimit, c.licenceno AS licenceno, c.licenceexpiry AS licenceepiry, c.salestaxregno AS salestaxregno, (SELECT r.name FROM dbo.region AS r WHERE (r.regioncode = ar.regioncode)) AS region, ar.name AS area, sa.name AS subarea, (SELECT m.description FROM dbo.message AS m WHERE (m.messagecode = c.messagecode)) AS message, (SELECT sm.name FROM dbo.salesman AS sm WHERE (sm.salesmancode = c.salesmancode)) AS salesperson, c.occupation AS occupation, c.designation AS designation, c.eduqualf AS education, c.bankname AS bank, c.bankadd AS bankaddress, c.gender AS gender, c.nic AS cnic, c.ntnno AS ntn, c.charges AS charges, tc.name AS taxcategory, tc.taxperc AS taxperc, c.salestaxexemption AS salestaxexemption FROM dbo.customer AS c, dbo.accounts AS a, dbo.customercategory AS cc, dbo.area AS ar, dbo.subarea AS sa, dbo.taxcategory AS tc WHERE (((((c.custcode = a.acccode) AND (c.custcatcode = cc.custcatcode)) AND (c.areacode = ar.areacode)) AND (c.subareacode = sa.subareacode)) AND (c.taxcategorycode = tc.taxcategorycode));

-- ==== view VIEW_WaseelaMini_Item ====
CREATE OR REPLACE VIEW dbo.view_waseelamini_item AS
SELECT i.icode AS icode, i.customicode AS customicode, i.name AS itemname, i.localitemname AS localitemname, i.packingdesc AS packingdesc, l.name AS itemclass, c.name AS itemcategory, (SELECT p.name FROM dbo.itempacking AS p WHERE (i.packcode = p.packcode)) AS itempacking, gi.name AS genericitem, m.name AS manufacturer, st.name AS salestaxschedule, st.taxperc AS taxperc, p.pctcode AS pctcode, i.saleprice AS saleprice, i.saleprice2 AS saleprice2, i.saleprice3 AS saleprice3, i.saleprice4 AS saleprice4, i.saleprice5 AS saleprice5, i.purprice AS purprice, i.retailprice AS retailprice, i.avgprice AS avgprice, i.flatdisc AS saleflatdisc, i.salediscperc AS salediscperc, i.purflatdisc AS purflatdisc, i.purdiscperc AS purdiscperc, i.packunits AS packunits, i.active AS active, i.prescribed AS prescribed, i.refrigrated AS refrigrated, i.printable AS printable, i.location1 AS location, i.remarks1 AS remarks, g.name AS associatedgodown, i.antinorcotix AS antinorcotics, i.gstperc1 AS gstperc1, i.gstperc2 AS gstperc2, i.packsalestax AS packsalestax, i.packingcost AS packingcost, i.recentpurprice AS recentpurprice, i.recentpurprice2 AS recentpurprice2, i.recentpurprice3 AS recentpurprice3, i.recentpurprice4 AS recentpurprice4, i.recentpurprice5 AS recentpurprice5, i.transitstock AS transitstock, i.taxable AS taxable, i.commissionperunit AS commissionperunit, i.commissionperc AS commissionperc, i.allowsaleindecimalqty AS allowsaleindecimalqty, i.length AS length, i.width AS width, i.areavolume AS area, i.thickness AS thickness, i.printitembatch AS printitembatch FROM dbo.item AS i, dbo.itemclass AS l, dbo.itemcategory AS c, dbo.manufacturer AS m, dbo.genericitem AS gi, dbo.godown AS g, dbo.salestaxschedule AS st, dbo.pct AS p WHERE (((((((i.iccode = l.iccode) AND (i.icatcode = c.icatcode)) AND (i.manfcode = m.manfcode)) AND (i.genericcode = gi.genericcode)) AND (i.gcode = g.gcode)) AND (i.salestaxschedulecode = st.salestaxschedulecode)) AND (i.pctcode = p.pctcode));

-- ==== view VIEW_WaseelaMini_Stock ====
CREATE OR REPLACE VIEW dbo.view_waseelamini_stock AS
SELECT i.icode AS icode, i.customicode AS customicode, i.name AS itemname, i.localitemname AS localitemname, i.packingdesc AS packingdesc, g.name AS godwon, gd.batch AS batch, gd.manfdate AS manfdate, gd.expiry AS expiry, gd.currqty AS qty, gd.priority AS priority FROM dbo.item AS i, dbo.godowndetail AS gd, dbo.godown AS g WHERE ((i.icode = gd.icode) AND (gd.gcode = g.gcode));

-- ==== view VIEW_WaseelaMini_StockSummary ====
CREATE OR REPLACE VIEW dbo.view_waseelamini_stocksummary AS
SELECT icode AS icode, coalesce(sum(currqty), 0) AS qty FROM dbo.godowndetail GROUP BY icode;

-- ==== view VIEW_WaseelaMini_Supplier ====
CREATE OR REPLACE VIEW dbo.view_waseelamini_supplier AS
SELECT s.suppcode AS suppcode, a.aliasname AS aliasname, a.name AS suppliername, sc.name AS suppliercategory, s.cp AS contactperson, s.address1 AS address1, s.address2 AS address2, s.city AS city, s.country AS country, s.mobileno AS cellno, s.phone AS phone, s.phone2 AS phone2, s.fax AS fax, s.email AS email, s.email2 AS email2, s.email3 AS email3, websiteadd AS web, s.dayslimit AS dayslimit, s.ntnno AS ntn, s.salestaxregno AS salestaxregno, s.cnic AS cnic, s.bankacc AS bank, s.whperc AS withholdingtaxperc FROM dbo.supplier AS s, dbo.accounts AS a, dbo.suppliercategory AS sc WHERE ((s.suppcode = a.acccode) AND (s.suppcatcode = sc.suppcatcode));
